select '8db2c535-5951-5150-8dde-96d61d458484', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.CTS'), 'qa_passed', 'continuous', '{"title":"Paneles solares en la vereda","text":"Una vereda sin conexión a la red eléctrica instala paneles solares en la escuela. Los paneles cargan baterías durante el día y de noche alimentan bombillos LED y un computador. En los meses de más lluvia, las baterías a veces no alcanzan a cargarse por completo.","svg":null,"table":null}'::jsonb, '¿Qué beneficio trae este proyecto a la vereda?', '[{"label":"A","text":"Gasolina más barata para los carros.","is_correct":false,"distractor_type":"Confunde fuentes de energía.","explanation_feedback":"Incorrecta. Los paneles no producen gasolina."},{"label":"B","text":"Más lluvia en la vereda.","is_correct":false,"distractor_type":"Inventa un efecto.","explanation_feedback":"Incorrecta. Los paneles no producen lluvia."},{"label":"C","text":"Electricidad en la escuela sin depender de la red.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Los paneles generan energía en el mismo lugar."},{"label":"D","text":"Agua potable para todas las casas.","is_correct":false,"distractor_type":"Inventa un efecto.","explanation_feedback":"Incorrecta. El proyecto produce electricidad, no agua."}]'::jsonb, null, 0.9, -1.2, 0.25, 40, 'original_generated'
