select '68d7495f-de2a-546e-8002-de4b514b65fb', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.CTS'), 'qa_passed', 'continuous', '{"title":"Paneles solares en la vereda","text":"Una vereda sin conexión a la red eléctrica instala paneles solares en la escuela. Los paneles cargan baterías durante el día y de noche alimentan bombillos LED y un computador. En los meses de más lluvia, las baterías a veces no alcanzan a cargarse por completo.","svg":null,"table":null}'::jsonb, '¿Por qué las baterías se cargan menos en meses lluviosos?', '[{"label":"A","text":"Porque el agua conduce la energía fuera de los paneles.","is_correct":false,"distractor_type":"Inventa un mecanismo.","explanation_feedback":"Incorrecta. No es lo que explica la menor carga."},{"label":"B","text":"Porque en esos meses los bombillos gastan menos.","is_correct":false,"distractor_type":"Invierte la relación.","explanation_feedback":"Incorrecta. Si gastaran menos, sobraría carga."},{"label":"C","text":"Porque las nubes reducen la luz solar que llega a los paneles.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Menos radiación solar significa menos energía generada."},{"label":"D","text":"Porque la lluvia daña las baterías dentro de la escuela.","is_correct":false,"distractor_type":"Inventa una causa.","explanation_feedback":"Incorrecta. Las baterías están protegidas; el problema es la luz."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
