select '7c111600-8e7f-54d5-9258-0c0fff14347f', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.CTS'), 'qa_passed', 'continuous', '{"title":"Paneles solares en la vereda","text":"Una vereda sin conexión a la red eléctrica instala paneles solares en la escuela. Los paneles cargan baterías durante el día y de noche alimentan bombillos LED y un computador. En los meses de más lluvia, las baterías a veces no alcanzan a cargarse por completo.","svg":null,"table":null}'::jsonb, '¿Qué uso de la energía sería más adecuado en días nublados?', '[{"label":"A","text":"Usar el computador toda la noche.","is_correct":false,"distractor_type":"Ignora la limitación de energía.","explanation_feedback":"Incorrecta. Agotaría las baterías."},{"label":"B","text":"Conectar más aparatos para aprovechar la energía.","is_correct":false,"distractor_type":"Ignora la menor generación.","explanation_feedback":"Incorrecta. Las baterías se descargarían antes."},{"label":"C","text":"Priorizar lo esencial, como la iluminación, y limitar el uso del computador.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Con menos energía almacenada, conviene reservarla para lo indispensable."},{"label":"D","text":"Desconectar los paneles para protegerlos.","is_correct":false,"distractor_type":"Elimina la poca carga posible.","explanation_feedback":"Incorrecta. Aun nublado, los paneles generan algo."}]'::jsonb, null, 1.3, 1.3, 0.25, 60, 'original_generated'
