select 'bb36c9ff-178c-5b40-b6b3-6ce38a5af834', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.CTS'), 'qa_passed', 'continuous', '{"title":"Plásticos de un solo uso","text":"Muchos plásticos de un solo uso, como pitillos y bolsas, tardan cientos de años en degradarse. En el mar se fragmentan en pedazos muy pequeños llamados microplásticos, que pueden ser ingeridos por peces y aves. Algunas ciudades han prohibido ciertos plásticos de un solo uso.","svg":null,"table":null}'::jsonb, '¿Qué efecto ambiental de estos plásticos describe el texto?', '[{"label":"A","text":"Se fragmentan en microplásticos que pueden comer los animales marinos.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Es la consecuencia que menciona el texto."},{"label":"B","text":"Se degradan en pocas semanas en el mar.","is_correct":false,"distractor_type":"Contradice el texto.","explanation_feedback":"Incorrecta. Tardan cientos de años."},{"label":"C","text":"Aumentan la población de peces.","is_correct":false,"distractor_type":"Inventa un efecto.","explanation_feedback":"Incorrecta. El texto habla de daño a los animales."},{"label":"D","text":"Producen oxígeno en el agua.","is_correct":false,"distractor_type":"Inventa un efecto.","explanation_feedback":"Incorrecta. Los plásticos no producen oxígeno."}]'::jsonb, null, 1.1, 0, 0.25, 50, 'original_generated'
