select 'a306a061-81b7-5bed-b68e-03a9fddb0d1b', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.CTS'), 'qa_passed', 'continuous', '{"title":"Plásticos de un solo uso","text":"Muchos plásticos de un solo uso, como pitillos y bolsas, tardan cientos de años en degradarse. En el mar se fragmentan en pedazos muy pequeños llamados microplásticos, que pueden ser ingeridos por peces y aves. Algunas ciudades han prohibido ciertos plásticos de un solo uso.","svg":null,"table":null}'::jsonb, '¿Qué medida reduce el problema desde su origen?', '[{"label":"A","text":"Quemar los plásticos en patios abiertos.","is_correct":false,"distractor_type":"Genera otro problema.","explanation_feedback":"Incorrecta. La quema a cielo abierto contamina el aire."},{"label":"B","text":"Enterrar los plásticos en las playas.","is_correct":false,"distractor_type":"Desplaza el problema.","explanation_feedback":"Incorrecta. El plástico seguiría en el ambiente."},{"label":"C","text":"Disminuir el uso de plásticos de un solo uso y reemplazarlos por reutilizables.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Si se producen y usan menos, llegan menos al mar."},{"label":"D","text":"Recoger solo los plásticos grandes de las playas.","is_correct":false,"distractor_type":"Atiende parte del problema al final.","explanation_feedback":"Incorrecta. Los microplásticos seguirían allí."}]'::jsonb, null, 1.3, 1.3, 0.25, 60, 'original_generated'
