select '2203b92e-0bfd-56c4-8d1c-6f75751a7876', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.CTS'), 'qa_passed', 'continuous', '{"title":"Plásticos de un solo uso","text":"Muchos plásticos de un solo uso, como pitillos y bolsas, tardan cientos de años en degradarse. En el mar se fragmentan en pedazos muy pequeños llamados microplásticos, que pueden ser ingeridos por peces y aves. Algunas ciudades han prohibido ciertos plásticos de un solo uso.","svg":null,"table":null}'::jsonb, '¿Qué evidencia ayudaría a saber si la prohibición en una ciudad funcionó?', '[{"label":"A","text":"Comparar la cantidad de plásticos en sus playas antes y después de la prohibición.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Medir el cambio permite evaluar el efecto de la medida."},{"label":"B","text":"Contar cuántas tiendas venden pitillos de colores.","is_correct":false,"distractor_type":"Mide algo poco relacionado.","explanation_feedback":"Incorrecta. No mide la contaminación."},{"label":"C","text":"Revisar si la prohibición salió en televisión.","is_correct":false,"distractor_type":"Mide la difusión, no el efecto.","explanation_feedback":"Incorrecta. Que se conozca no prueba que funcione."},{"label":"D","text":"Preguntar a los turistas si les gusta la playa.","is_correct":false,"distractor_type":"Usa opiniones en lugar de mediciones.","explanation_feedback":"Incorrecta. El gusto no mide la cantidad de plásticos."}]'::jsonb, null, 1.1, 0, 0.25, 60, 'original_generated'
