select '83bb31c1-64f9-5990-a3ac-7d2f2c48ae34', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.CTS'), 'qa_passed', 'continuous', '{"title":"Agua lluvia para regar","text":"En un colegio rural se recoge el agua lluvia del techo en un tanque para regar la huerta. Algunos estudiantes quieren usarla también para beber.","svg":null,"table":null}'::jsonb, '¿Por qué no es recomendable beber el agua del tanque sin tratarla?', '[{"label":"A","text":"Porque el agua lluvia es siempre salada.","is_correct":false,"distractor_type":"Inventa una propiedad.","explanation_feedback":"Incorrecta. El agua lluvia no es salada."},{"label":"B","text":"Porque el agua lluvia no tiene hidrógeno.","is_correct":false,"distractor_type":"Inventa una composición.","explanation_feedback":"Incorrecta. El agua lluvia es H₂O."},{"label":"C","text":"Porque las plantas ya usaron toda el agua.","is_correct":false,"distractor_type":"Inventa una razón.","explanation_feedback":"Incorrecta. El tanque tiene agua disponible."},{"label":"D","text":"Puede contener microorganismos y suciedad del techo y del tanque.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El agua lluvia arrastra contaminantes del techo y puede tener microorganismos."}]'::jsonb, null, 1.1, 0, 0.25, 50, 'original_generated'
