select 'f42d388f-956c-5d47-a0c4-ec4647e67247', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.CTS'), 'qa_passed', 'continuous', '{"title":"Agua lluvia para regar","text":"En un colegio rural se recoge el agua lluvia del techo en un tanque para regar la huerta. Algunos estudiantes quieren usarla también para beber.","svg":null,"table":null}'::jsonb, '¿Qué procedimiento haría más segura el agua para beber?', '[{"label":"A","text":"Filtrarla y luego hervirla o desinfectarla.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El filtro quita partículas y hervir o desinfectar elimina microorganismos."},{"label":"B","text":"Agregarle azúcar al tanque.","is_correct":false,"distractor_type":"Confunde sabor con seguridad.","explanation_feedback":"Incorrecta. El azúcar no elimina microorganismos."},{"label":"C","text":"Dejarla al sol en el tanque abierto varios días.","is_correct":false,"distractor_type":"Expone el agua a más contaminación.","explanation_feedback":"Incorrecta. Un tanque abierto acumula suciedad y zancudos."},{"label":"D","text":"Enfriarla en la nevera.","is_correct":false,"distractor_type":"Confunde temperatura con desinfección.","explanation_feedback":"Incorrecta. El frío no elimina los microorganismos."}]'::jsonb, null, 1.1, 0, 0.25, 50, 'original_generated'
