select '3d688530-414b-57fb-9fe1-3bc78895dd70', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.CTS'), 'qa_passed', 'continuous', '{"title":"Agua lluvia para regar","text":"En un colegio rural se recoge el agua lluvia del techo en un tanque para regar la huerta. Algunos estudiantes quieren usarla también para beber.","svg":null,"table":null}'::jsonb, '¿Qué ventaja ambiental tiene usar el agua lluvia para la huerta?', '[{"label":"A","text":"Aumenta la lluvia en la zona.","is_correct":false,"distractor_type":"Inventa un efecto.","explanation_feedback":"Incorrecta. Recoger agua no cambia la lluvia."},{"label":"B","text":"Se ahorra agua del acueducto o de fuentes naturales.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El agua lluvia reemplaza otra fuente para el riego."},{"label":"C","text":"Hace que las plantas no necesiten luz.","is_correct":false,"distractor_type":"Inventa un efecto.","explanation_feedback":"Incorrecta. Las plantas siguen necesitando luz."},{"label":"D","text":"Elimina la necesidad de suelo.","is_correct":false,"distractor_type":"Inventa un efecto.","explanation_feedback":"Incorrecta. La huerta sigue necesitando suelo."}]'::jsonb, null, 0.9, -1.2, 0.25, 40, 'original_generated'
