select '100e83dd-bb14-5180-9731-23652d69f3e1', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.CTS'), 'qa_passed', 'continuous', '{"title":"Celulares y radiación","text":"Los celulares emiten ondas de radio, un tipo de radiación electromagnética no ionizante, de baja energía. Los rayos X y la radiación ultravioleta del sol tienen más energía por fotón y en dosis altas pueden dañar el ADN de las células.","svg":null,"table":null}'::jsonb, '¿Qué diferencia a las ondas de los celulares de los rayos X, según el texto?', '[{"label":"A","text":"Las ondas de los celulares no son electromagnéticas.","is_correct":false,"distractor_type":"Contradice el texto.","explanation_feedback":"Incorrecta. Son radiación electromagnética."},{"label":"B","text":"Las ondas de los celulares tienen menos energía por fotón.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El texto dice que son no ionizantes y de baja energía."},{"label":"C","text":"Los rayos X tienen menos energía.","is_correct":false,"distractor_type":"Invierte la comparación.","explanation_feedback":"Incorrecta. Los rayos X tienen más energía."},{"label":"D","text":"Los rayos X son ondas de sonido.","is_correct":false,"distractor_type":"Confunde tipos de onda.","explanation_feedback":"Incorrecta. Los rayos X son electromagnéticos."}]'::jsonb, null, 1.1, 0, 0.25, 50, 'original_generated'
