select '4dfa46bb-9d3b-51f5-918e-1221e14c9597', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.CTS'), 'qa_passed', 'continuous', '{"title":"Celulares y radiación","text":"Los celulares emiten ondas de radio, un tipo de radiación electromagnética no ionizante, de baja energía. Los rayos X y la radiación ultravioleta del sol tienen más energía por fotón y en dosis altas pueden dañar el ADN de las células.","svg":null,"table":null}'::jsonb, '¿Por qué se recomienda usar bloqueador solar?', '[{"label":"A","text":"Porque la radiación ultravioleta en exceso puede dañar el ADN de las células de la piel.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El texto indica que la UV puede dañar el ADN en dosis altas."},{"label":"B","text":"Porque el sol emite rayos X en grandes cantidades a la superficie.","is_correct":false,"distractor_type":"Exagera un dato.","explanation_feedback":"Incorrecta. El texto habla de la radiación ultravioleta del sol."},{"label":"C","text":"Porque las ondas del celular queman la piel.","is_correct":false,"distractor_type":"Confunde los tipos de radiación.","explanation_feedback":"Incorrecta. El texto dice que son de baja energía."},{"label":"D","text":"Porque la luz visible no llega a la piel.","is_correct":false,"distractor_type":"Contradice la experiencia.","explanation_feedback":"Incorrecta. La luz visible sí llega."}]'::jsonb, null, 1.3, 1.3, 0.25, 60, 'original_generated'
