select '18fd2512-1edc-5dd7-9f81-a79308b72c61', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.CTS'), 'qa_passed', 'continuous', '{"title":"Biocombustibles","text":"En Colombia se mezcla la gasolina con etanol producido a partir de caña de azúcar. El etanol es renovable porque la caña vuelve a crecer y absorbe CO₂ mientras crece. Sin embargo, aumentar mucho los cultivos de caña puede requerir más tierra y agua.","svg":null,"table":null}'::jsonb, '¿Por qué se considera que el etanol de caña es renovable?', '[{"label":"A","text":"Porque se extrae del subsuelo como el petróleo.","is_correct":false,"distractor_type":"Confunde con combustibles fósiles.","explanation_feedback":"Incorrecta. El petróleo no es renovable."},{"label":"B","text":"Porque no produce ningún gas al quemarse.","is_correct":false,"distractor_type":"Exagera la ventaja.","explanation_feedback":"Incorrecta. El etanol también produce CO₂ al quemarse."},{"label":"C","text":"Porque no necesita agua ni tierra.","is_correct":false,"distractor_type":"Contradice el texto.","explanation_feedback":"Incorrecta. La caña necesita tierra y agua."},{"label":"D","text":"Porque la caña se puede volver a sembrar y crecer en poco tiempo.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. La fuente se regenera a escala humana."}]'::jsonb, null, 1.1, 0, 0.25, 50, 'original_generated'
