select '5de922ed-753c-56bb-9af9-e1a575778231', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.CTS'), 'qa_passed', 'continuous', '{"title":"Biocombustibles","text":"En Colombia se mezcla la gasolina con etanol producido a partir de caña de azúcar. El etanol es renovable porque la caña vuelve a crecer y absorbe CO₂ mientras crece. Sin embargo, aumentar mucho los cultivos de caña puede requerir más tierra y agua.","svg":null,"table":null}'::jsonb, '¿Qué posible efecto negativo de ampliar mucho los cultivos de caña señala el texto?', '[{"label":"A","text":"Eliminar por completo el CO₂ del aire.","is_correct":false,"distractor_type":"Exagera un efecto.","explanation_feedback":"Incorrecta. La caña absorbe algo de CO₂, pero no todo."},{"label":"B","text":"Mayor demanda de tierra y agua, que puede competir con otros usos.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El texto advierte sobre la necesidad de más tierra y agua."},{"label":"C","text":"Aumentar la cantidad de petróleo en el subsuelo.","is_correct":false,"distractor_type":"Inventa un efecto.","explanation_feedback":"Incorrecta. Los cultivos no generan petróleo."},{"label":"D","text":"Reducir la producción de etanol.","is_correct":false,"distractor_type":"Invierte el efecto.","explanation_feedback":"Incorrecta. Más caña produciría más etanol."}]'::jsonb, null, 1.3, 1.3, 0.25, 60, 'original_generated'
