select 'e24954ef-dd9a-5574-a413-5bd2151d4b1f', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.CTS'), 'qa_passed', 'continuous', '{"title":"Fertilizantes en el lago","text":"Cerca de un lago, varios cultivos usan fertilizantes con nitrógeno y fósforo. Con las lluvias, parte del fertilizante llega al lago. Los pescadores notan que el agua se volvió verde por el crecimiento de algas y que aparecen peces muertos.","svg":null,"table":null}'::jsonb, '¿Qué explica la muerte de los peces?', '[{"label":"A","text":"Las algas producen tanto oxígeno que los peces se ahogan.","is_correct":false,"distractor_type":"Invierte el efecto.","explanation_feedback":"Incorrecta. El problema es la falta de oxígeno."},{"label":"B","text":"Los peces se comen el fertilizante y se intoxican.","is_correct":false,"distractor_type":"Propone un mecanismo menos probable.","explanation_feedback":"Incorrecta. El efecto principal es la falta de oxígeno."},{"label":"C","text":"El agua verde es demasiado fría para los peces.","is_correct":false,"distractor_type":"Inventa un efecto térmico.","explanation_feedback":"Incorrecta. El color no enfría el agua."},{"label":"D","text":"Las algas crecen en exceso, luego mueren y su descomposición consume el oxígeno del agua.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Es el proceso de eutrofización: los descomponedores gastan el oxígeno."}]'::jsonb, null, 1.3, 1.3, 0.25, 90, 'original_generated'
